function(container, apiUrl, tables) {
  // 今日の日付を取得
  const today = new Date().toISOString().split('T')[0];
  const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  const oneMonthAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  // 初期値設定
  container.querySelector('#prediction-start-date').value = tomorrow;
  container.querySelector('#prediction-end-date').value = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  container.querySelector('#learning-start-date').value = oneMonthAgo;
  container.querySelector('#learning-end-date').value = today;

  // 店舗データの読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品カテゴリの読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryContainer = container.querySelector('#category-checkboxes');
    const categories = new Set();

    if (products) {
      products.forEach(product => {
        if (product.有効フラグ && product.AI予測対象フラグ) {
          categories.add(product.商品カテゴリID);
        }
      });

      categories.forEach(categoryId => {
        const label = document.createElement('label');
        label.style.display = 'block';
        label.style.marginBottom = '5px';
        label.innerHTML = `<input type="checkbox" class="category-checkbox" value="${categoryId}"> カテゴリ ${categoryId.substring(0, 8)}...`;
        categoryContainer.appendChild(label);
      });
    }
  }

  // 全選択チェックボックスの処理
  container.querySelector('#select-all-categories').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.category-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // 季節要因スライダーの値表示更新
  container.querySelector('#seasonal-factor').addEventListener('input', function() {
    container.querySelector('#seasonal-value').textContent = this.value + '%';
  });

  // 天候データ取込ボタン
  container.querySelector('#btn-weather-import').addEventListener('click', async function() {
    this.disabled = true;
    this.textContent = '取込中...';

    try {
      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 成功メッセージ
      const message = document.createElement('div');
      message.style.color = 'var(--primary)';
      message.style.fontSize = '12px';
      message.style.marginTop = '5px';
      message.textContent = '天候データの取込が完了しました';
      this.parentNode.appendChild(message);

      setTimeout(() => {
        if (message.parentNode) {
          message.parentNode.removeChild(message);
        }
      }, 3000);

    } catch (error) {
      // エラーメッセージ
      const message = document.createElement('div');
      message.style.color = '#ff6a00';
      message.style.fontSize = '12px';
      message.style.marginTop = '5px';
      message.textContent = '天候データの取得に失敗しました。データソースの設定を確認してください。';
      this.parentNode.appendChild(message);
    } finally {
      this.disabled = false;
      this.textContent = '天候データ取込';
    }
  });

  // イベントデータ取込ボタン
  container.querySelector('#btn-event-import').addEventListener('click', async function() {
    this.disabled = true;
    this.textContent = '取込中...';

    try {
      // 模擬的なイベントデータ取込処理
      await new Promise(resolve => setTimeout(resolve, 1500));

      // 成功メッセージ
      const message = document.createElement('div');
      message.style.color = 'var(--primary)';
      message.style.fontSize = '12px';
      message.style.marginTop = '5px';
      message.textContent = 'イベントデータの取込が完了しました';
      this.parentNode.appendChild(message);

      setTimeout(() => {
        if (message.parentNode) {
          message.parentNode.removeChild(message);
        }
      }, 3000);

    } catch (error) {
      // エラーメッセージ
      const message = document.createElement('div');
      message.style.color = '#ff6a00';
      message.style.fontSize = '12px';
      message.style.marginTop = '5px';
      message.textContent = 'イベントデータの取込に失敗しました。ファイル形式を確認してください。';
      this.parentNode.appendChild(message);
    } finally {
      this.disabled = false;
      this.textContent = 'イベントデータ取込';
    }
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    // 予測期間チェック
    const startDate = container.querySelector('#prediction-start-date').value;
    const endDate = container.querySelector('#prediction-end-date').value;
    if (!startDate || !endDate) {
      errors.push('予測期間の開始日と終了日を入力してください');
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();

      if (start < today || end < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    // 店舗選択チェック
    if (!container.querySelector('#store-select').value) {
      errors.push('店舗を選択してください');
    }

    // 商品カテゴリチェック
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }

    // 予測モデルチェック
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }

    // 学習データ期間チェック
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間の開始日と終了日を入力してください');
    } else {
      const lStart = new Date(learningStart);
      const lEnd = new Date(learningEnd);
      const pStart = new Date(startDate);

      const learningDays = Math.ceil((lEnd - lStart) / (1000 * 60 * 60 * 24));
      const predictionDays = Math.ceil((new Date(endDate) - pStart) / (1000 * 60 * 60 * 24));

      if (learningDays < predictionDays) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // AI予測実行ボタン
  container.querySelector('#btn-execute-prediction').addEventListener('click', async function() {
    const errors = validateForm();
    if (errors.length > 0) {
      alert(errors.join('\n'));
      return;
    }

    // UI無効化
    this.disabled = true;
    this.textContent = '予測実行中...';
    const allInputs = container.querySelectorAll('input, select, button');
    allInputs.forEach(input => input.disabled = true);

    // 進捗バー表示
    const progressContainer = container.querySelector('#progress-container');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const resultContainer = container.querySelector('#result-container');

    progressContainer.classList.remove('hidden');
    resultContainer.classList.add('hidden');

    try {
      // 模擬的な予測処理（段階的に進捗更新）
      const steps = [
        { progress: 10, text: 'データ収集中...' },
        { progress: 30, text: '前処理実行中...' },
        { progress: 50, text: 'モデル学習中...' },
        { progress: 70, text: '予測計算中...' },
        { progress: 90, text: '結果生成中...' },
        { progress: 100, text: '完了' }
      ];

      for (const step of steps) {
        await new Promise(resolve => setTimeout(resolve, 1000));
        progressBar.style.width = step.progress + '%';
        progressText.textContent = step.text;
      }

      // 予測結果の生成と保存
      const selectedCategories = Array.from(container.querySelectorAll('.category-checkbox:checked')).map(cb => cb.value);
      const storeId = container.querySelector('#store-select').value;
      const startDate = container.querySelector('#prediction-start-date').value;
      const endDate = container.querySelector('#prediction-end-date').value;
      const model = container.querySelector('input[name="prediction-model"]:checked').value;
      const accuracyThreshold = parseFloat(container.querySelector('#accuracy-threshold').value);

      // 模擬予測結果データ
      const results = [];
      const stores = await window.aivicApi.list(1);
      const products = await window.aivicApi.list(2);
      const selectedStore = stores?.find(s => s.店舗ID === storeId);

      if (selectedStore && products) {
        const targetProducts = products.filter(p => 
          selectedCategories.includes(p.商品カテゴリID) && 
          p.有効フラグ && 
          p.AI予測対象フラグ
        );

        for (const product of targetProducts.slice(0, 10)) { // 最大10件まで表示
          const accuracy = Math.random() * (1 - accuracyThreshold) + accuracyThreshold;
          const predictedQty = Math.floor(Math.random() * 100) + 10;
          const recommendedQty = Math.floor(predictedQty * 1.1);

          const result = {
            店舗ID: storeId,
            商品ID: product.商品ID,
            予測対象日: startDate,
            予測数量: predictedQty,
            予測精度: accuracy,
            推奨発注数量: recommendedQty,
            予測モデルバージョン: model + '_v1.0',
            予測ステータス: '完了',
            発注済フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          };

          // 需要予測結果テーブルに保存
          await window.aivicApi.save(9, result);

          results.push({
            店舗名: selectedStore.店舗名,
            商品名: product.商品名,
            予測日: startDate,
            予測数量: predictedQty,
            予測精度: (accuracy * 100).toFixed(1) + '%',
            推奨発注数量: recommendedQty
          });
        }
      }

      // 結果表示
      const resultTbody = container.querySelector('#result-tbody');
      resultTbody.innerHTML = results.map(r => `
        <tr>
          <td>${r.店舗名}</td>
          <td>${r.商品名}</td>
          <td>${r.予測日}</td>
          <td>${r.予測数量}</td>
          <td>${r.予測精度}</td>
          <td>${r.推奨発注数量}</td>
        </tr>
      `).join('');

      resultContainer.classList.remove('hidden');

    } catch (error) {
      alert('AI予測実行が失敗しました。システム管理者にお問い合わせください。');
    } finally {
      // UI復元
      allInputs.forEach(input => input.disabled = false);
      this.disabled = false;
      this.textContent = 'AI予測実行';
      progressContainer.classList.add('hidden');
    }
  });

  // 初期データ読み込み
  loadStores();
  loadCategories();
}
